package cache

import (
	"container/list"
	"sync"
)

// LRU is a fixed-capacity least-recently-used cache.
// It is safe for concurrent use.
type LRU struct {
	capacity   int
	elements   *list.List
	entries    map[string]*list.Element
	lock       sync.Mutex
}

type entry struct {
	key   string
	value int
}

// NewLRU returns a new LRU cache with the given capacity.
// A non-positive capacity means the cache never retains anything.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		elements:  list.New(),
		entries:   make(map[string]*list.Element),
	}
}

// Get returns the value stored for key and reports whether it was found.
// Accessing a key marks it as most recently used.
func (c *LRU) Get(key string) (int, bool) {
	c.lock.Lock()
	defer c.lock.Unlock()

	elem, ok := c.entries[key]
	if !ok {
		return 0, false
	}
	c.elements.MoveToFront(elem)
	return elem.Value.(*entry).value, true
}

// Put stores value under key. Updating an existing key does not grow the
// cache; adding a new key when full evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	if c.capacity <= 0 {
		return
	}

	c.lock.Lock()
	defer c.lock.Unlock()

	if elem, ok := c.entries[key]; ok {
		elem.Value.(*entry).value = value
		c.elements.MoveToFront(elem)
		return
	}

	c.elements.PushFront(&entry{key: key, value: value})
	c.entries[key] = c.elements.Front()

	if len(c.entries) > c.capacity {
		lru := c.elements.Back()
		delete(c.entries, lru.Value.(*entry).key)
		c.elements.Remove(lru)
	}
}

// Len returns the number of entries currently in the cache.
func (c *LRU) Len() int {
	c.lock.Lock()
	defer c.lock.Unlock()
	return len(c.entries)
}

